package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
	"unicode"
	"unicode/utf8"
)

type AuditEntry struct {
	Timestamp time.Time
	User      string
	Action    string
	Resource  string
	Hash      string
}

type SearchIndex struct {
	mu      sync.RWMutex
	entries map[string][]string
	acl     map[string][]string
	audit   []AuditEntry
}

func NewSearchIndex() *SearchIndex {
	return &SearchIndex{
		entries: make(map[string][]string),
		acl:     make(map[string][]string),
		audit:   make([]AuditEntry, 0),
	}
}

func (si *SearchIndex) computeResourceHash(resource string) string {
	h := sha256.New()
	h.Write([]byte(resource))
	return hex.EncodeToString(h.Sum(nil))
}

func (si *SearchIndex) normalizeIdentifier(input string) string {
	var builder strings.Builder
	for _, r := range input {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '-' || r == '.' {
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

func (si *SearchIndex) validateResourceName(name string) bool {
	if len(name) == 0 || len(name) > 256 {
		return false
	}
	if !utf8.ValidString(name) {
		return false
	}
	for _, r := range name {
		if unicode.Is(unicode.Mn, r) {
			return false
		}
	}
	return true
}

func (si *SearchIndex) checkAccess(user, resource string) bool {
	si.mu.RLock()
	defer si.mu.RUnlock()
	normalizedUser := si.normalizeIdentifier(user)
	allowedResources, exists := si.acl[normalizedUser]
	if !exists {
		return false
	}
	for _, allowed := range allowedResources {
		if allowed == resource {
			return true
		}
	}
	return false
}

func (si *SearchIndex) logAccess(user, action, resource string) {
	entry := AuditEntry{
		Timestamp: time.Now(),
		User:      user,
		Action:    action,
		Resource:  resource,
		Hash:      si.computeResourceHash(resource),
	}
	si.audit = append(si.audit, entry)
}

func (si *SearchIndex) AddDocument(user, resource, content string) error {
	if !si.validateResourceName(resource) {
		return fmt.Errorf("invalid resource name")
	}
	if !si.checkAccess(user, resource) {
		si.mu.Lock()
		si.logAccess(user, "DENIED_ADD", resource)
		si.mu.Unlock()
		return fmt.Errorf("access denied")
	}
	si.mu.Lock()
	defer si.mu.Unlock()
	si.entries[resource] = append(si.entries[resource], content)
	si.logAccess(user, "ADD", resource)
	return nil
}

func (si *SearchIndex) Search(user, query string) ([]string, error) {
	normalizedQuery := si.normalizeIdentifier(query)
	si.mu.RLock()
	defer si.mu.RUnlock()
	var results []string
	for resource, docs := range si.entries {
		if !si.checkAccessUnlocked(user, resource) {
			continue
		}
		for _, doc := range docs {
			if strings.Contains(strings.ToLower(doc), strings.ToLower(normalizedQuery)) {
				results = append(results, doc)
			}
		}
	}
	return results, nil
}

func (si *SearchIndex) checkAccessUnlocked(user, resource string) bool {
	normalizedUser := si.normalizeIdentifier(user)
	allowedResources, exists := si.acl[normalizedUser]
	if !exists {
		return false
	}
	for _, allowed := range allowedResources {
		if allowed == resource {
			return true
		}
	}
	return false
}

func (si *SearchIndex) GrantAccess(admin, user, resource string) error {
	if !si.checkAccess(admin, "_admin") {
		return fmt.Errorf("not authorized")
	}
	si.mu.Lock()
	defer si.mu.Unlock()
	normalizedUser := si.normalizeIdentifier(user)
	si.acl[normalizedUser] = append(si.acl[normalizedUser], resource)
	si.logAccess(admin, "GRANT", fmt.Sprintf("%s->%s", normalizedUser, resource))
	return nil
}

func (si *SearchIndex) GetAuditLog(admin string) ([]AuditEntry, error) {
	if !si.checkAccess(admin, "_admin") {
		return nil, fmt.Errorf("not authorized")
	}
	si.mu.RLock()
	defer si.mu.RUnlock()
	return si.audit, nil
}

func main() {
	idx := NewSearchIndex()
	idx.mu.Lock()
	idx.acl["admin"] = []string{"_admin", "docs", "secrets"}
	idx.acl["alice"] = []string{"docs"}
	idx.mu.Unlock()

	http.HandleFunc("/search", func(w http.ResponseWriter, r *http.Request) {
		user := r.Header.Get("X-User")
		query := r.URL.Query().Get("q")
		results, err := idx.Search(user, query)
		if err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		for _, res := range results {
			fmt.Fprintf(w, "%s\n", res)
		}
	})

	http.HandleFunc("/grant", func(w http.ResponseWriter, r *http.Request) {
		admin := r.Header.Get("X-User")
		targetUser := r.URL.Query().Get("user")
		resource := r.URL.Query().Get("resource")
		if err := idx.GrantAccess(admin, targetUser, resource); err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		fmt.Fprintf(w, "granted\n")
	})

	log.Fatal(http.ListenAndServe(":8080", nil))
}
